   218→        onAction: () => navigate("/app/zip-codes"),
   219→      }}
   220→    >
   221→      <Box paddingBlockEnd="1600">
   222→        <BlockStack gap="500">
   223→
   224→          {/* ─── 1. APP STATUS ─── */}
   225→          {appEmbedEnabled ? (
   226→            <Banner
   227→              tone="success"
   228→              title="Widget is live on your store"
   229→              action={{
   230→                content: "Open Theme Editor",
   231→                url: themeEditorUrl,
   232→                external: true,
   233→              }}
   234→            >
   235→              <Text as="p" variant="bodySm">
   236→                {activeThemeName
   237→                  ? `Running on your ${activeThemeName} theme. `
   238→                  : ""}
   239→                Any changes you make here apply to your storefront instantly.
   240→              </Text>
   241→            </Banner>
   242→          ) : (
   243→            <Banner
   244→              tone="warning"
   245→              title="2 steps to show the widget on your store"
   246→              action={{
   247→                content: "Enable in Theme Editor",
   248→                url: themeEditorAppEmbedsUrl,
   249→                external: true,
   250→              }}
   251→              secondaryAction={{
   252→                content: revalidateState === "loading" ? "Checking..." : "Refresh status",
   253→                onAction: revalidate,
   254→              }}
   255→            >
   256→              <List type="number">
   257→                <List.Item>
   258→                  Open <strong>Theme Editor &gt; App Embeds</strong> and turn on{" "}
   259→                  <strong>Pinzo</strong>
   260→                </List.Item>
   261→                <List.Item>
   262→                  Go to your <strong>Product template</strong>, add the{" "}
   263→                  <strong>Pinzo</strong> block, and save
   264→                </List.Item>
   265→              </List>
   266→            </Banner>
   267→          )}
   268→
   269→          {/* ─── 2. STATS ─── */}
   270→          {!isEmpty && (
   271→            <Card>
   272→              <BlockStack gap="400">
   273→                <InlineGrid columns={{ xs: 2, sm: 3, md: 5 }} gap="400">
   274→                  <BlockStack gap="100">
   275→                    <Text as="p" variant="headingXl" fontWeight="bold">
   276→                      {stats.total}
   277→                      {limits.maxZipCodes < UNLIMITED && (
   278→                        <Text as="span" variant="bodySm" tone="subdued" fontWeight="regular">
   279→                          {" "}/ {limits.maxZipCodes}
   280→                        </Text>
   281→                      )}
   282→                    </Text>
   283→                    <Text as="p" variant="bodySm" tone="subdued">
   284→                      Zip codes
   285→                    </Text>
   286→                  </BlockStack>
   287→
   288→                  <BlockStack gap="100">
   289→                    <Text as="p" variant="headingXl" fontWeight="bold" tone="success">
   290→                      {stats.allowed}
   291→                    </Text>
   292→                    <Text as="p" variant="bodySm" tone="subdued">
   293→                      Serviceable
   294→                    </Text>
   295→                  </BlockStack>
   296→
   297→                  <BlockStack gap="100">
   298→                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.blocked > 0 ? "critical" : "subdued"}>
   299→                      {stats.blocked}
   300→                    </Text>
   301→                    <Text as="p" variant="bodySm" tone="subdued">
   302→                      Blocked
   303→                    </Text>
   304→                  </BlockStack>
   305→
   306→                  <BlockStack gap="100">
   307→                    <Text as="p" variant="headingXl" fontWeight="bold" tone={stats.waitlist > 0 ? "caution" : "subdued"}>
   308→                      {stats.waitlist}
   309→                    </Text>
   310→                    <Text as="p" variant="bodySm" tone="subdued">
   311→                      Waitlisted
   312→                    </Text>
   313→                  </BlockStack>
   314→
   315→                  <BlockStack gap="100">
   316→                    <Text as="p" variant="headingXl" fontWeight="bold">
   317→                      {stats.deliveryRules}
   318→                    </Text>
   319→                    <Text as="p" variant="bodySm" tone="subdued">
   320→                      Delivery rules
   321→                    </Text>
   322→                  </BlockStack>
   323→                </InlineGrid>
   324→
   325→                {/* Usage bar — shown when plan has a finite zip limit */}
   326→                {hasZipLimit && (
   327→                  <>
   328→                    <Divider />
   329→                    <BlockStack gap="200">
   330→                      <InlineStack align="space-between">
   331→                        <Text as="p" variant="bodySm" tone="subdued">
   332→                          Plan usage
   333→                        </Text>
   334→                        <Text as="p" variant="bodySm" fontWeight="semibold" tone={usagePercent >= 80 ? "critical" : "subdued"}>
   335→                          {usagePercent}%
   336→                        </Text>
   337→                      </InlineStack>
   338→                      <ProgressBar
   339→                        progress={usagePercent}
   340→                        tone={usagePercent >= 80 ? "critical" : "highlight"}
   341→                        size="small"
   342→                      />
   343→                    </BlockStack>
   344→                  </>
   345→                )}
   346→              </BlockStack>
   347→            </Card>
   348→          )}
   349→
   350→          {/* ─── 3. UPGRADE PROMPT ─── */}
   351→          {hasZipLimit && !isEmpty && usagePercent >= 60 && (
   352→            <Banner
   353→              tone="warning"
   354→              action={{
   355→                content: isFreePlan ? "Upgrade to Starter" : "Upgrade to Pro",
   356→                onAction: () => navigate("/app/pricing"),
   357→              }}
   358→            >
   359→              <Text as="p" variant="bodySm">
   360→                You&apos;re using {stats.total} of {limits.maxZipCodes} zip codes on the {planLabel} plan.
   361→                {isFreePlan
   362→                  ? " Upgrade to Starter for 500 zip codes, delivery rules, and more."
   363→                  : " Upgrade to Pro for unlimited zip codes, blocked zones, and full features."}
   364→              </Text>
   365→            </Banner>
   366→          )}
   367→
   368→          {/* ─── 4. GETTING STARTED (dismissible onboarding) ─── */}
   369→          {isEmpty && !onboardingDismissed && (
   370→            <Card>
   371→              <BlockStack gap="400">
   372→                <InlineStack align="space-between" blockAlign="center">
   373→                  <Text as="h2" variant="headingMd">
   374→                    Get started
   375→                  </Text>
   376→                  <Button variant="plain" onClick={handleDismissOnboarding}>
   377→                    Dismiss
   378→                  </Button>
   379→                </InlineStack>
   380→                <InlineGrid columns={{ xs: 1, sm: 3 }} gap="400">
   381→                  {[
   382→                    {
   383→                      step: "1",
   384→                      title: "Add zip codes",
   385→                      desc: "Enter the zip codes you deliver to, or import them via CSV.",
   386→                      action: "Add zip codes",
   387→                      href: "/app/zip-codes",
   388→                      primary: true,
   389→                    },
   390→                    {
   391→                      step: "2",
   392→                      title: "Customize the widget",
   393→                      desc: "Set colors, text, and position to match your store.",
   394→                      action: "Customize",
   395→                      href: "/app/widget",
   396→                      primary: false,
   397→                    },
   398→                    {
   399→                      step: "3",
   400→                      title: "Add delivery rules",
   401→                      desc: "Set delivery fees, cutoff times, and schedules per zone.",
   402→                      action: "Add rules",
   403→                      href: "/app/delivery-rules",
   404→                      primary: false,
   405→                    },
   406→                  ].map((item) => (
   407→                    <Box
   408→                      key={item.step}
   409→                      padding="400"
   410→                      background="bg-surface-secondary"
   411→                      borderRadius="300"
   412→                    >
   413→                      <BlockStack gap="200">
   414→                        <InlineStack gap="200" blockAlign="center">
   415→                          <Box
   416→                            background="bg-fill-brand"
   417→                            borderRadius="full"
   418→                            padding="100"
   419→                            minWidth="24px"
   420→                            minHeight="24px"
   421→                          >
   422→                            <Text
   423→                              as="span"
   424→                              variant="bodySm"
   425→                              fontWeight="bold"
   426→                              alignment="center"
   427→                              tone="text-inverse"
   428→                            >
   429→                              {item.step}
   430→                            </Text>
   431→                          </Box>
   432→                          <Text as="h3" variant="headingSm">
   433→                            {item.title}
   434→                          </Text>
   435→                        </InlineStack>
   436→                        <Text as="p" variant="bodySm" tone="subdued">
   437→                          {item.desc}
   438→                        </Text>
   439→                        <Button
   440→                          variant={item.primary ? "primary" : undefined}
   441→                          size="slim"
   442→                          onClick={() => navigate(item.href)}
   443→                        >
   444→                          {item.action}
   445→                        </Button>
   446→                      </BlockStack>
   447→                    </Box>
   448→                  ))}
   449→                </InlineGrid>
   450→              </BlockStack>
   451→            </Card>
   452→          )}
   453→
   454→          {/* ─── 5. NAVIGATION ─── */}
   455→          <InlineGrid columns={{ xs: 1, sm: 2, md: 4 }} gap="400">
   456→            {[
   457→              {
   458→                title: "Zip Codes",
   459→                desc: "Add, edit, import, or export your service areas.",
   460→                stat: stats.total > 0 ? `${stats.total} total` : undefined,
   461→                action: "Manage zip codes",
   462→                href: "/app/zip-codes",
   463→              },
   464→              {
   465→                title: "Delivery Rules",
   466→                desc: "Set fees, cutoff times, and schedules by zone.",
   467→                stat: stats.deliveryRules > 0 ? `${stats.deliveryRules} rules` : undefined,
   468→                action: "Manage rules",
   469→                href: "/app/delivery-rules",
   470→              },
   471→              {
   472→                title: "Waitlist",
   473→                desc: "View customers requesting delivery to new areas.",
   474→                stat: stats.waitlist > 0 ? `${stats.waitlist} waiting` : undefined,
   475→                action: "View waitlist",
   476→                href: "/app/waitlist",
   477→              },
   478→              {
   479→                title: "Widget",
   480→                desc: "Customize colors, text, and layout on your store.",
   481→                action: "Customize widget",
   482→                href: "/app/widget",
   483→              },
   484→            ].map((item) => (
   485→              <Card key={item.title}>
   486→                <BlockStack gap="200">
   487→                  <InlineStack align="space-between" blockAlign="center">
   488→                    <Text as="h3" variant="headingSm">
   489→                      {item.title}
   490→                    </Text>
   491→                    {item.stat && (
   492→                      <Badge tone="info">{item.stat}</Badge>
   493→                    )}
   494→                  </InlineStack>
   495→                  <Text as="p" variant="bodySm" tone="subdued">
   496→                    {item.desc}
   497→                  </Text>
   498→                  <Button
   499→                    size="slim"
   500→                    onClick={() => navigate(item.href)}
   501→                  >
   502→                    {item.action}
   503→                  </Button>
   504→                </BlockStack>
   505→              </Card>
   506→            ))}
   507→          </InlineGrid>
   508→
   509→        </BlockStack>
   510→      </Box>
   511→    </Page>
   512→  );
   513→}
   514→
   515→export function ErrorBoundary() {
   516→  return boundary.error(useRouteError());
   517→}
   518→
   519→export const headers: HeadersFunction = (headersArgs) => {
   520→  return boundary.headers(headersArgs);
   521→};
